import importlib.util
spec=importlib.util.spec_from_file_location('taskprog', program_file)
taskprog=importlib.util.module_from_spec(spec); spec.loader.exec_module(taskprog)
def make_demo(h,w,bg,frames):
    g=[[bg]*w for _ in range(h)]
    for r,c,size,color,_ in frames:
        for y in range(r,r+size):
            for x in range(c,c+size):
                if y in (r,r+size-1) or x in (c,c+size-1): g[y][x]=color
    return g
def expected_demo(g, frames):
    e=[row[:] for row in g]
    for r,c,size,color,fill in frames:
        for y in range(r+1,r+size-1):
            for x in range(c+1,c+size-1): e[y][x]=fill
    return e
frames1=[(1,3,5,5,7),(5,11,7,1,7),(18,3,5,1,7),(20,15,4,3,2),(24,10,3,5,7)]
demo1=make_demo(29,20,8,frames1)
frames2=[(0,5,4,8,2),(5,0,7,4,7),(4,12,6,3,2),(11,18,3,1,7),(15,20,6,9,2),(20,12,4,4,2)]
demo2=make_demo(25,27,0,frames2)
assert taskprog.transform(demo1)==expected_demo(demo1,frames1)
assert taskprog.transform(demo2)==expected_demo(demo2,frames2)
print('both demonstrations reproduced')
